import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"安装","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/installation.md","filePath":"zh-CN/guide/installation.md","lastUpdated":1793173149000}`),a={name:`zh-CN/guide/installation.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h1><p>Sudoku 已在 App Store 上架，是一款通用 App，一次购买即可在 iPhone、iPad 和 Mac 上使用。</p><h2 id="下载" tabindex="-1">下载 <a class="header-anchor" href="#下载" aria-label="Permalink to “下载”">​</a></h2><ul><li><strong>App Store</strong>：<a href="https://apps.apple.com/app/id6793606018" target="_blank" rel="noreferrer">下载 Sudoku</a> —— 支持 iPhone、iPad 与 Mac 的通用 App</li></ul><h3 id="app-store-推荐" tabindex="-1">App Store（推荐） <a class="header-anchor" href="#app-store-推荐" aria-label="Permalink to “App Store（推荐）”">​</a></h3><p>App Store 版本可自动更新，并与你的所有 Apple 设备无缝集成。</p><ul><li><strong>App Store ID</strong>：6793606018</li><li><strong>链接</strong>：<a href="https://apps.apple.com/app/id6793606018" target="_blank" rel="noreferrer">https://apps.apple.com/app/id6793606018</a></li><li><strong>平台</strong>：iPhone、iPad、Mac（通用 App）</li><li><strong>价格</strong>：请查看 App Store 页面了解当前价格</li></ul><h2 id="安装步骤" tabindex="-1">安装步骤 <a class="header-anchor" href="#安装步骤" aria-label="Permalink to “安装步骤”">​</a></h2><h3 id="iphone-ipad" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad" aria-label="Permalink to “iPhone / iPad”">​</a></h3><ol><li>在设备上打开 <strong>App Store</strong></li><li>搜索“Sudoku”，或使用上面的直接链接</li><li>点按 <strong>获取</strong> 或 <strong>购买</strong> 进行下载</li><li>应用会自动安装</li><li>从主屏幕启动 Sudoku</li></ol><h3 id="mac" tabindex="-1">Mac <a class="header-anchor" href="#mac" aria-label="Permalink to “Mac”">​</a></h3><ol><li>在 Mac 上打开 <strong>App Store</strong></li><li>搜索“Sudoku”，或使用上面的直接链接</li><li>点按 <strong>获取</strong> 或 <strong>购买</strong> 完成购买</li><li>应用会自动下载并安装</li><li>从“应用程序”文件夹或启动台启动 Sudoku</li></ol><h2 id="首次启动" tabindex="-1">首次启动 <a class="header-anchor" href="#首次启动" aria-label="Permalink to “首次启动”">​</a></h2><p>首次启动 Sudoku 时，应用会请求访问 iCloud（用于同步）和 Game Center（用于排行榜和成就）的权限。这两项都是可选的——不授予权限也能完整离线游玩。</p><h2 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to “更新”">​</a></h2><p>更新由 App Store 自动处理。如需手动检查更新，请打开 App Store，进入 <strong>账户 → 更新</strong> 页面。</p><h2 id="卸载" tabindex="-1">卸载 <a class="header-anchor" href="#卸载" aria-label="Permalink to “卸载”">​</a></h2><h3 id="iphone-ipad-1" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad-1" aria-label="Permalink to “iPhone / iPad”">​</a></h3><ol><li>长按 Sudoku 应用图标</li><li>点按 <strong>移除 App</strong> → <strong>删除 App</strong></li></ol><h3 id="mac-1" tabindex="-1">Mac <a class="header-anchor" href="#mac-1" aria-label="Permalink to “Mac”">​</a></h3><ol><li>退出 Sudoku</li><li>将 <code>Sudoku.app</code> 从 <code>Applications</code> 拖到废纸篓</li><li>（可选）清除应用数据：</li></ol><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.sudoku</span></span></code></pre></div><h2 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to “系统要求”">​</a></h2><ul><li><strong>iPhone/iPad</strong>：iOS/iPadOS 16.0 或更高版本</li><li><strong>Mac</strong>：macOS 15.0（Sequoia）或更高版本</li><li><strong>CPU</strong>：Apple Silicon（M 系列）</li><li><strong>内存</strong>：最低 2GB</li><li><strong>存储空间</strong>：约 50 MB</li><li><strong>网络</strong>：游玩不需要网络（iCloud 和 Game Center 为可选）</li></ul><h2 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to “故障排查”">​</a></h2><p>如果安装过程中遇到问题：</p><ul><li><strong>macOS 阻止了应用运行</strong>：打开 <strong>系统设置 → 隐私与安全性</strong>，然后为 Sudoku 点按 <strong>仍要打开</strong></li><li><strong>应用没有出现</strong>：重启 App Store 或你的设备后重试</li></ul><p>如需更多帮助，请参阅<a href="./troubleshooting.html">故障排查指南</a>，或在项目仓库中提交 issue。</p>`,28)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};